      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory transformed the quantitative understanding of correlated-electron materials and remains a central bridge between model physics and realistic spectra.",
        "attribution": "The three named scientists represent the foundational formulation and establishment of the method, though its subsequent development was broad.",
        "maturity": "The method has been tested across decades against experiments and is deeply embedded in modern materials theory.",
        "uncertainties": [
          "A prize would need to define whether the principal achievement is the original theory or its extensive later computational development."
        ]
      }
    },
