      "ballot_id": "B050",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "Topological insulators and the quantum spin Hall effect revealed a durable new organizing principle for electronic states of matter.",
        "attribution": "Kane and Mele supplied the decisive theoretical framework, while Molenkamp led a defining experimental realization.",
        "maturity": "The effect has been independently reproduced, extensively characterized, and has generated a major field.",
        "uncertainties": [
          "The appropriate balance between theoretical prediction and the several experimental confirmations requires careful delimitation."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Harald Rose",
        "Knut Urban",
        "Maximilian Haider"
      ],
      "assessment": {
        "nobel_worthiness": "Aberration correction made routine sub-angstrom electron microscopy possible, changing the experimental basis of materials physics.",
        "attribution": "Rose provided crucial optical concepts, and Haider and Urban were central to practical correction and its materials-science realization.",
        "maturity": "Its performance, reproducibility, and impact are firmly established across laboratories.",
        "uncertainties": [
          "The long technical lineage of electron-optical correction may make precise priority boundaries difficult."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B039",
      "proposed_laureates": [
        "Shinji Yuasa",
        "Stuart S. P. Parkin",
        "William H. Butler"
      ],
      "assessment": {
        "nobel_worthiness": "Giant tunnel magnetoresistance in crystalline MgO junctions united a clear quantum-transport mechanism with transformative spintronic technology.",
        "attribution": "Yuasa and Parkin supplied landmark experimental demonstrations, while Butler identified the symmetry-filtering mechanism.",
        "maturity": "The phenomenon is quantitatively understood, independently confirmed, and central to magnetic-memory devices.",
        "uncertainties": [
          "Credit must distinguish this advance from the earlier discovery of giant magnetoresistance."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "These phase effects established that global quantum structure has observable physical consequences, with influence from condensed matter to precision experiments.",
        "attribution": "Aharonov is central to the experimentally consequential electromagnetic phase effect, and Berry to the general adiabatic geometric phase.",
        "maturity": "Both concepts are longstanding, experimentally secure, and foundational in current quantum materials research.",
        "uncertainties": [
          "The two effects differ historically and conceptually, so their combination in one prize would need a particularly coherent citation."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Kenji Watanabe",
        "Takashi Taniguchi"
      ],
      "assessment": {
        "nobel_worthiness": "Ultrapure hexagonal boron nitride enabled the clean van der Waals heterostructures from which much modern two-dimensional quantum physics has grown.",
        "attribution": "Watanabe and Taniguchi are the clearest central figures in producing the exceptional hBN crystals; broader heterostructure advances involve many groups.",
        "maturity": "The material platform is reproducible and indispensable to numerous established observations.",
        "uncertainties": [
          "Its enabling role may be judged less distinct than a single fundamental discovery."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer",
        "Allan H. MacDonald"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle graphene uncovered a striking route to correlated and superconducting states engineered through moiré structure.",
        "attribution": "Jarillo-Herrero led the seminal experiments, while Bistritzer and MacDonald provided the decisive theoretical account of the magic-angle bands.",
        "maturity": "The central moiré-band physics has been widely reproduced and has launched a broad materials platform.",
        "uncertainties": [
          "The microscopic origins and universality of several correlated phases remain actively debated."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B046",
      "proposed_laureates": [
        "Mehran Kardar",
        "Yi-Cheng Zhang",
        "Kazumasa A. Takeuchi"
      ],
      "assessment": {
        "nobel_worthiness": "The KPZ universality class gave a powerful, unexpected description of non-equilibrium fluctuations across otherwise disparate physical systems.",
        "attribution": "Kardar and Zhang introduced the defining framework, and Takeuchi provided unusually decisive quantitative experimental tests.",
        "maturity": "Exact results and high-precision experiments now establish the universality class convincingly.",
        "uncertainties": [
          "The contribution is mathematically and experimentally profound, but its public-facing physical realization is less singular than some leading candidates."
        ]
      }
    }
  ]
